"""Build the D'Andrea content into the retained industrial presentation layout."""
import json,pathlib,html,urllib.parse,re
ROOT=pathlib.Path(__file__).resolve().parents[1];DIST=ROOT/'dist'
D=json.loads((ROOT/'content/site.json').read_text(encoding='utf-8'));C=D['company'];CATS=D['categories'];PRODUCTS=D['products']
ORIGIN='https://demakine-base-industrial-alan.alaanhenriquee94.chatgpt.site'
def e(s):return html.escape(str(s),quote=True)
def caturl(c):return '/solucoes/'+c['slug']+'/'
def purl(p):return '/produtos/'+p['slug']+'/'
def img(src,alt='',cls='',eager=False):return f'<img src="{e(src)}" alt="{e(alt)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async">'
def btn(text,url,kind='primary'):return f'<a class="btn {kind}" href="{e(url)}">{text}<span aria-hidden="true">↗</span></a>'
def form(prefix='main',product=''):
 return f'''<form class="quote-form" id="{prefix}-form"><h3>Peça seu orçamento</h3><p>Conte o que a sua operação precisa.</p><div class="form-grid"><label><span>Nome completo</span><input name="name" autocomplete="name" placeholder="Nome completo*" required></label><label><span>Telefone</span><input type="tel" name="phone" autocomplete="tel" placeholder="Telefone / WhatsApp*" required></label><label><span>Empresa</span><input name="company" autocomplete="organization" placeholder="Empresa*" required></label><label><span>E-mail</span><input type="email" name="email" autocomplete="email" placeholder="E-mail*" required></label></div><label><span>Mensagem</span><textarea name="message" placeholder="Conte o que precisa: produto, aplicação e capacidade*" required>{e('Gostaria de informações sobre '+product+'.' if product else '')}</textarea></label><button class="btn green" type="submit">Solicitar orçamento <span aria-hidden="true">↗</span></button><small>Versão de revisão: o formulário ainda não envia dados.</small><p class="form-status" role="status" hidden></p></form>'''
def header():
 nav=f'<a href="/">Início</a><a href="/a-empresa/">Nossa história</a><a href="/produtos/">Todas as soluções</a>'+''.join(f'<a href="{caturl(c)}">{e(c["name"])}</a>' for c in CATS)+'<a href="/contato/">Contato</a>'
 return f'''<a class="skip" href="#main">Ir para o conteúdo</a><div class="topbar"><div class="wrap"><span>Máquinas e soluções industriais · Desde 1934 · Brasil e Estados Unidos</span><a href="tel:+551936711858">☎ {C['phone']}</a></div></div><header class="site-header"><div class="wrap header-row"><a href="/" aria-label="D’Andrea, página inicial">{img(C['headerLogo'],'DA — D’Andrea Company','logo',True)}</a><nav class="desktop-nav" aria-label="Navegação principal"><a href="/a-empresa/">Nossa história</a><a href="/produtos/">Soluções</a><a href="/contato/">Contato</a></nav><div class="header-actions">{btn('Pedir orçamento','/contato/#formulario')}<button class="menu-toggle" aria-label="Abrir menu" aria-expanded="false" aria-controls="main-menu">☰</button></div></div><nav id="main-menu" class="mobile-menu wrap" aria-label="Menu completo" hidden>{nav}</nav></header>'''
def footer():
 return f'''<footer><div class="wrap footer-grid"><div><a href="/">{img(C['logo'],'D’Andrea Company','footer-logo')}</a><h3>Seu sonho realizado</h3><p>Soluções para conversão de papel, embalagens, papel tissue e equipamentos complementares.</p><div class="social">{''.join(f'<a href="{v}" target="_blank" rel="noopener noreferrer">{k} ↗</a>' for k,v in C['social'].items())}</div></div><div><h4>Soluções</h4>{''.join(f'<a href="{caturl(c)}">{e(c["name"])}</a>' for c in CATS)}</div><div><h4>Institucional</h4><a href="/">Início</a><a href="/a-empresa/">Nossa história</a><a href="/contato/">Fale conosco</a><a href="https://dandrea.com.br/privacy-policy/" target="_blank" rel="noopener noreferrer">Política de privacidade ↗</a></div><div><h4>Brasil</h4><p>{C['brazilAddress']}</p><a href="tel:+551936711858">{C['phone']}</a><a href="tel:+5519998575484">{C['mobile'][0]}</a><a href="tel:+5519996869561">{C['mobile'][1]}</a><h4 class="mt">Estados Unidos</h4><p>{C['usAddress']}</p><a href="tel:+9547370330">{C['usPhone']}</a></div></div><div class="wrap footer-bottom"><span>© 2026 D’Andrea Company. Todos os direitos reservados.</span><span>Inovando · Construindo · Superando, sempre</span><a href="#top">Voltar ao topo ↑</a></div></footer><a class="floating-contact" href="/contato/" aria-label="Fale com a D’Andrea">✉</a><dialog id="image-dialog"><button class="dialog-close" aria-label="Fechar imagem">×</button><img alt=""><p></p></dialog>'''
def layout(title,body,path,desc='Soluções D’Andrea para conversão de papel, embalagens, tissue e equipamentos complementares. Desde 1934.'):
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="{e(desc)}"><title>{e(title)} | D’Andrea Company</title><meta property="og:title" content="{e(title)} | D’Andrea Company"><meta property="og:description" content="{e(desc)}"><meta property="og:image" content="{ORIGIN}/media/bg.jpg"><link rel="canonical" href="{ORIGIN}{path}"><link rel="icon" href="/media/da-logo.png"><link rel="stylesheet" href="/assets/fonts.css"><link rel="stylesheet" href="/assets/dandrea.css?v=logos-20261104"><script src="/assets/dandrea.js" defer></script></head><body id="top">{header()}<main id="main">{body}</main>{footer()}</body></html>'''
def write(path,title,body,desc=None):
 p=DIST/path.strip('/')/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(layout(title,body,path,**({'desc':desc} if desc else {})),encoding='utf-8')
def intro(eyebrow,title,description='',image='/media/bg.jpg'):
 return f'<section class="page-hero" style="--page-image:url(\'{image}\')"><div class="wrap"><nav class="breadcrumbs" aria-label="Você está aqui"><a href="/">Início</a><span>/</span><span>{e(eyebrow)}</span></nav><p class="eyebrow light">{e(eyebrow)}</p><h1>{e(title)}</h1><p>{e(description)}</p></div></section>'
def card(p):
 cat=next(c for c in CATS if c['slug']==p['category'])
 return f'<article class="product-card" data-category="{cat["slug"]}" data-search="{e(p["name"]+" "+p["description"])}"><a href="{purl(p)}">{img(p["image"],p["name"])}<div class="card-copy"><span class="eyebrow">{e(cat["short"])}</span><h3>{e(p["name"])}</h3><p>{e(p["description"])}</p><strong>Ver detalhes <span>↗</span></strong></div></a></article>'
def cards(items):return '<div class="product-grid">'+''.join(card(p) for p in items)+'</div>'
def categories():
 return '<div class="category-grid">'+''.join(f'<a class="category-card" href="{caturl(c)}">{img(c["image"],c["name"])}<div><span class="eyebrow">0{i+1} · {len(c["products"])} soluções</span><h3>{e(c["name"])}</h3><span class="arrow">↗</span></div></a>' for i,c in enumerate(CATS))+'</div>'
def contact(product=''):
 return f'''<section class="section contact-section" id="formulario"><div class="wrap contact-grid"><div><p class="eyebrow">Fale com a D’Andrea</p><h2>Onde quer que você esteja,<br>estamos aqui para servi-lo.</h2><p class="lead">Entre em contato com nossa equipe e conte sobre a sua operação.</p><div class="address"><span class="country">🇧🇷</span><div><h3>Brasil</h3><p>{C['brazilAddress']}</p><a href="tel:+551936711858">{C['phone']}</a><a href="tel:+5519998575484">{C['mobile'][0]}</a><a href="tel:+5519996869561">{C['mobile'][1]}</a><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=Av.+Peri+Igel+1040+Casa+Branca+SP" target="_blank" rel="noopener noreferrer">Ver localização ↗</a></div></div><div class="address"><span class="country">🇺🇸</span><div><h3>Estados Unidos</h3><p>{C['usAddress']}</p><a href="tel:+9547370330">{C['usPhone']}</a><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=305+Maltbie+Industrial+Dr+Lawrenceville+GA+30046" target="_blank" rel="noopener noreferrer">Ver localização ↗</a></div></div></div>{form('contact',product)}</div></section>'''
def cta():return '<section class="cta"><div class="wrap"><div><p class="eyebrow light">Sua próxima solução</p><h2>Vamos conversar sobre a sua produção?</h2></div>'+btn('Falar com a equipe','/contato/','white')+'</div></section>'
def home():
 feature=[]
 for i,c in enumerate(CATS):
  p=next(p for p in PRODUCTS if p['slug']==c['products'][0])
  feature.append(f'<div class="featured-panel" id="feature-{i}" role="tabpanel" aria-labelledby="feature-tab-{i}" {"hidden" if i else ""}><div><p class="eyebrow">{e(c["name"])}</p><h2>{e(p["name"])}</h2><p class="lead">{e(p["description"])}</p><div class="actions">{btn("Pedir orçamento","/contato/?produto="+urllib.parse.quote(p["name"])+"#formulario")}{btn("Ver detalhes",purl(p),"outline")}</div></div><a class="feature-image" href="{purl(p)}">{img(p["image"],p["name"])}</a></div>')
 historyintro=next(x['text'] for x in D['history'] if x['type']=='text')
 quote=[x for x in D['history'] if x['type']=='text'][-1]
 return f'''<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><p class="red-label">D’Andrea Company · Desde 1934</p><h1>90 ANOS<br>IMPULSIONANDO<br><em>O SEU SUCESSO</em></h1><p class="hero-subtitle">Inovando · Construindo · Superando, sempre</p><div class="red-rule"></div><p class="lead">Máquinas e soluções para conversão de papel, embalagens, papel tissue e equipamentos complementares.</p>{btn('Conhecer todas as soluções','/produtos/','white')}<a class="hero-secondary" href="#linhas">Qual é a sua aplicação? Conheça nossas linhas →</a><div class="hero-stats"><div><strong>1934</strong><span>Início da nossa história</span></div><div><strong>100+</strong><span>Países com máquinas D’Andrea</span></div><div><strong>4</strong><span>Linhas de soluções</span></div></div></div>{form('hero')}</div></section><div class="ticker"><div>Conversão de papel <b>✦</b> Embalagens <b>✦</b> Papel tissue <b>✦</b> Equipamentos complementares <b>✦</b> Desde 1934 <b>✦</b> Brasil e Estados Unidos</div></div><section class="section featured"><div class="wrap">{''.join(feature)}<div class="feature-tabs" role="tablist" aria-label="Linhas de soluções">{''.join(f'<button type="button" id="feature-tab-{i}" role="tab" aria-selected="{str(i==0).lower()}" aria-controls="feature-{i}" data-feature="{i}"><span>0{i+1}</span>{e(c["name"])}</button>' for i,c in enumerate(CATS))}</div></div></section><section class="section soft"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Nossas soluções</p><h2>Tecnologia para cada etapa<br>da sua produção</h2><p>Conheça as soluções D’Andrea para a indústria de papel e embalagens.</p></div>{btn('Ver as 24 soluções','/produtos/','outline')}</div>{cards([PRODUCTS[i] for i in [0,1,3,6,9,10,17,23]])}</div></section><section class="section" id="linhas"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Linhas de soluções</p><h2>Do papel ao produto acabado</h2></div></div>{categories()}</div></section><section class="section history-summary"><div class="wrap split"><a class="history-photo" href="/a-empresa/">{img('/media/familia_dandrea.png','Família D’Andrea')}<span>Conheça nossa história ↗</span></a><div><p class="eyebrow">Quem é a D’Andrea</p><h2>Uma história que começou em 1934.<br>Um legado que segue em movimento.</h2><p class="lead">{e(historyintro)}</p><div class="small-stats"><div><strong>1934</strong><span>Fundação em Limeira/SP</span></div><div><strong>100+</strong><span>Países atendidos ao longo da história</span></div></div>{btn('Nossa história','/a-empresa/')}</div></div></section><section class="brand-banner" style="--banner:url('/media/atlanta-unsplash-e1717897039287.jpg')"><div class="wrap"><p class="eyebrow light">D’Andrea Company</p><h2>Onde quer que você esteja,<br>estamos aqui para servi-lo.</h2>{btn('Entre em contato','/contato/','white')}</div></section><section class="section"><div class="wrap"><p class="eyebrow">Presença e compromisso</p><div class="values-grid"><div class="value-image">{img('/media/eagle-constitution-flag-e1717897104821.jpg','Símbolos dos Estados Unidos')}<h2>Comprometidos com<br>os valores americanos</h2></div><div class="value-image">{img('/media/bg.jpg','Máquinas D’Andrea')}<h2>Inovando. Construindo.<br>Superando, sempre.</h2></div></div></div></section><section class="section quote-section"><div class="wrap quote-grid">{img('/media/sergio.jpg','Sergio D’Andrea')}<div><p class="eyebrow">Um compromisso com o futuro</p><blockquote>{''.join('<p>'+e(p)+'</p>' for p in (quote['paragraphs'] or [quote['text']]))}</blockquote></div></div></section>{contact()}'''
def catalog(category=None):
 title=category['name'] if category else 'Equipamentos para transformar papel em possibilidades'
 items=[p for p in PRODUCTS if not category or p['category']==category['slug']]
 head=intro(category['name'] if category else 'Catálogo de soluções',title,'Tecnologia D’Andrea para a sua operação. Explore os equipamentos e encontre sua solução.')
 filterbar='<div class="catalog-controls"><div class="filter-buttons" role="group" aria-label="Filtrar soluções"><button class="active" data-filter="all" aria-pressed="true">Todas <small>24</small></button>'+''.join(f'<button data-filter="{c["slug"]}" aria-pressed="false">{e(c["short"])} <small>{len(c["products"])}</small></button>' for c in CATS)+'</div><label class="search-label"><span>Buscar soluções</span><input type="search" id="catalog-search" placeholder="Buscar no catálogo…"></label></div>' if not category else '<label class="search-label category-search"><span>Buscar nesta linha</span><input type="search" id="catalog-search" placeholder="Buscar nesta linha…"></label>'
 return head+f'<section class="section"><div class="wrap" id="catalog">{filterbar}<p id="result-count" role="status">{len(items)} soluções</p>{cards(items)}<div id="empty-state" hidden><h2>Nenhuma solução encontrada</h2><p>Tente outro termo ou selecione outra linha.</p><button class="btn outline" id="clear-filters">Limpar busca</button></div></div></section>'+cta()
def product(p):
 cat=next(c for c in CATS if c['slug']==p['category'])
 return f'''<section class="section product-detail"><div class="wrap"><nav class="breadcrumbs dark" aria-label="Você está aqui"><a href="/">Início</a><span>/</span><a href="/produtos/">Soluções</a><span>/</span><a href="{caturl(cat)}">{e(cat['name'])}</a></nav><div class="split product-overview"><button class="gallery-image" data-zoom="{p['image']}" data-caption="{e(p['name'])}" aria-label="Ampliar imagem de {e(p['name'])}">{img(p['image'],p['name'],'',True)}<span>Ampliar imagem ⊕</span></button><div><p class="eyebrow">{e(cat['name'])}</p><h1>{e(p['name'])}</h1>{''.join('<p class="lead">'+e(t)+'</p>' for t in p['paragraphs'])}<div class="actions">{btn('Pedir orçamento','/contato/?produto='+urllib.parse.quote(p['name'])+'#formulario')}{btn('Assista aos vídeos',C['social']['YouTube'],'outline')}</div><a class="phone-link" href="tel:+551936711858">☎ {C['phone']}</a></div></div></div></section><section class="section soft"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Explore a linha</p><h2>Outras soluções em {e(cat['short'].lower())}</h2></div>{btn('Ver linha completa',caturl(cat),'outline')}</div>{cards([x for x in PRODUCTS if x['category']==p['category'] and x['slug']!=p['slug']][:3])}</div></section>{contact(p['name'])}'''
def history():
 parts=[]
 # Keep every public heading, paragraph and historical image in original order.
 for n in D['history']:
  if n['type']=='heading':parts.append('<h2>'+e(n['text'])+'</h2>')
  elif n['type']=='text':parts.append(''.join('<p>'+e(p)+'</p>' for p in (n['paragraphs'] or [n['text']])))
  else:parts.append(''.join('<figure>'+img(u,'Arquivo histórico D’Andrea')+'</figure>' for u in n['images']))
 return intro('Nossa história','A história de quase 100 anos da D’Andrea','Da iniciativa de uma família à tecnologia presente em mais de 100 países.')+'<section class="section"><div class="wrap history-layout"><aside class="history-aside"><p class="eyebrow">Nossa trajetória</p><strong>Desde<br>1934</strong><p>Pioneirismo, coragem e tecnologia a serviço da indústria.</p>'+btn('Conhecer soluções','/produtos/','outline')+'</aside><article class="history-article">'+''.join(parts)+'</article></div></section>'+cta()
write('/','Seu sonho realizado',home())
write('/produtos/','Todas as soluções',catalog())
for c in CATS:
 write(caturl(c),c['name'],catalog(c))
 write('/'+c['sourcePath']+'/',c['name'],catalog(c))
for p in PRODUCTS:write(purl(p),p['name'],product(p),p['description'])
write('/a-empresa/','Nossa história',history());write('/history/','Nossa história',history())
for route in ['/contato/','/contact-us/','/contact/']:write(route,'Entre em contato',intro('Contato','Vamos conversar sobre a sua produção','D’Andrea Company · Brasil e Estados Unidos')+contact())
(DIST/'404.html').write_text(layout('Página não encontrada',intro('Página não encontrada','Vamos encontrar a solução que você procura.')+'<section class="section"><div class="wrap">'+btn('Ver todas as soluções','/produtos/')+'</div></section>','/404.html'),encoding='utf-8')
(DIST/'_headers').write_text('/*\n  X-Robots-Tag: noindex, nofollow\n',encoding='utf-8')
print('Built',len(list(DIST.rglob('index.html'))),'pages; all',len(PRODUCTS),'source products included.')
